// Read-only date comparison ('is this reminder date today or in the
// past?') -- not a JobOS business rule, this is the one piece of
// logic the master task explicitly delegated to this workflow rather
// than to a new JobOS API concept.
const today = new Date().toISOString().slice(0, 10);
const body = $input.first().json;
const due = (body.follow_ups || []).filter((f) => f.follow_up_date <= today);
return due.map((f) => ({ json: { ...f, is_overdue: f.follow_up_date < today } }));

// Formats one human-readable log line per due/overdue follow-up.
// Wire a Slack/Email/Telegram node after this one to get an actual
// notification -- see this workflow's Setup Notes sticky.
return $input.all().map((item) => {
  const f = item.json;
  const tag = f.is_overdue ? 'OVERDUE' : 'DUE TODAY';
  return { json: { message: `[${tag}] ${f.title} at ${f.company} -- follow up by ${f.follow_up_date} (job_id=${f.job_id})` } };
});
